import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BL79I5mR.js";const u=JSON.parse('{"title":"Cross-Section Geometry","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/hydraulics/04-cross-section-geometry.md","filePath":"explanation/hydraulics/04-cross-section-geometry.md"}'),s={name:"explanation/hydraulics/04-cross-section-geometry.md"};function n(i,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="cross-section-geometry" tabindex="-1">Cross-Section Geometry <a class="header-anchor" href="#cross-section-geometry" aria-label="Permalink to &quot;Cross-Section Geometry&quot;">​</a></h1><h2 id="cross-section-geometry-1" tabindex="-1">Cross-section geometry <a class="header-anchor" href="#cross-section-geometry-1" aria-label="Permalink to &quot;Cross-section geometry&quot;">​</a></h2><h3 id="the-four-geometric-relations" tabindex="-1">The four geometric relations <a class="header-anchor" href="#the-four-geometric-relations" aria-label="Permalink to &quot;The four geometric relations&quot;">​</a></h3><p>For a conduit, the flow area $A$, top width $W$, wetted perimeter $P_w$, and hydraulic radius $R = A/P_w$ are functions of the flow depth $y$. The engine pre-computes, for each shape, the four fundamental relations (<code>XSectKernels.hpp</code>, <code>xsect_tables.hpp</code>):</p><p>$$ \\begin{aligned} A &amp;= A(y), \\qquad W = W(y), \\qquad R = R(y), \\ S &amp;= S(A) = A,R^{2/3} \\quad \\text{(section factor, &quot;conveyance shape&quot;),} \\end{aligned} $$</p><p>together with their inverses $y = y(A)$, $A = A(S)$, and the derivative $dS/dA$. Closed-form expressions exist for the standard shapes (circular, filled circular, rectangular, trapezoidal, triangular, parabolic, power, eggs, horseshoe, gothic, basket-handle, etc.); irregular and custom shapes use tabulated (transect) tables with linear interpolation, and the inverse $A(S)$ is solved by Newton iteration or table inversion.</p><h3 id="manning-and-the-section-factor" tabindex="-1">Manning and the section factor <a class="header-anchor" href="#manning-and-the-section-factor" aria-label="Permalink to &quot;Manning and the section factor&quot;">​</a></h3><p>Manning&#39;s equation in US customary form is</p><p>$$Q = \\frac{1.486}{n},A,R^{2/3},\\sqrt{S_f} = \\beta,\\Psi(A),\\sqrt{S_f/S_0}, \\qquad \\Psi(A) = A,R^{2/3},$$</p><p>where $S_f$ is the friction slope, $\\beta = (1.486/n)\\sqrt{S_0}$, and $\\Psi(A)$ is the section factor. For many closed shapes the section factor peaks below full depth, so the maximum discharge occurs at a less-than-full area.</p>',10)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
